<script lang="ts">
 import {onMount,onDestroy,untrack} from 'svelte';import {anyApi} from 'convex/server';import {auth} from '#lib/auth.svelte.ts';import {app} from '#lib/state.svelte.ts';import {feed} from '#lib/feed.svelte.ts';
 import {evidenceShortlist} from '#lib/evidence-shortlist.js';import {evidenceSlipPick} from '#lib/evidence-slip.js';import {startEvidenceRefresh} from '#lib/evidence-refresh.js';import {rolloverTickets,rolloverDay,rolloverStreak} from '#lib/rollover.js';
 let allowed=$state(false),checked=$state(false),loading=$state(false),error=$state(''),notice=$state(''),report=$state<any>(null),now=$state(Date.now()),selected=$state(rolloverDay(Date.now())),updated=$state(0);let records=$state<any[]>([]),saving=$state(false);let controller:AbortController|undefined,etag='',disposed=false;
 const dates=$derived(Array.from({length:60},(_,i)=>rolloverDay(now+(i-29)*86400000)));
 $effect(()=>{const client=auth.client;if(!client){checked=true;allowed=false;report=null;return;}return client.onUpdate(anyApi.admin.status,{},r=>{allowed=r?.isSuperAdmin===true;checked=true;if(!allowed){report=null;etag='';controller?.abort();}},()=>{checked=true;allowed=false;report=null;});});
 $effect(()=>{if(!allowed||!auth.client)return;return auth.client.onUpdate(anyApi.evidence.meta,{},meta=>untrack(()=>{if(!meta||etag!==`"${meta.version}"`)void load();else updated=meta.updatedAt;}),()=>{error='Evidence connection interrupted. Automatic retry is active.';});});
 $effect(()=>{if(!allowed||!auth.client){records=[];return;}return auth.client.onUpdate(anyApi.rollover.history,{},r=>records=r,()=>error='Recorded rollover results could not load.');});
 onMount(()=>startEvidenceRefresh({refresh:load,canRefresh:()=>allowed&&!loading,onTick:()=>{now=Date.now();if(selected<rolloverDay(now))selected=rolloverDay(now);}}));onDestroy(()=>{disposed=true;controller?.abort();});
 async function load(){if(!allowed||loading||disposed)return;loading=true;error='';const request=controller=new AbortController(),timer=setTimeout(()=>request.abort(),20000);try{const r=await fetch('/api/admin/evidence',{headers:etag?{'If-None-Match':etag}:{},cache:'no-store',signal:request.signal});if(r.status===304){updated=Number(r.headers.get('X-Evidence-Checked-At'))||updated;return;}if(!r.ok)throw Error(`Evidence unavailable (HTTP ${r.status}).`);let bytes=new Uint8Array(await r.arrayBuffer());if(bytes[0]===31&&bytes[1]===139)bytes=new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer());if(bytes.length>64*1024*1024)throw Error('Evidence exceeds the display budget.');const data=JSON.parse(new TextDecoder().decode(bytes));if(data.schema!==1||!Array.isArray(data.upcoming)||!data.groups)throw Error('Invalid evidence catalog.');if(disposed||!allowed||request.signal.aborted)return;report=data;etag=r.headers.get('ETag')??'';updated=Number(r.headers.get('X-Evidence-Checked-At'))||data.generatedAt;now=Date.now();}catch(e){if(allowed&&!disposed)error=(e as Error).message;}finally{clearTimeout(timer);loading=false;}}
 const rows=$derived(report?evidenceShortlist(report,{hours:168,catalogCheckedAt:updated,includePeriodForecasts:false},now,new Map((feed.data?.games??[]).map(g=>[g.id,g]))).rows:[]);
 // Current quotes must agree with the published option. No fair-price substitution.
 const priced=$derived(rows.filter((r:any)=>rolloverDay(r.kickoff)===selected&&r.kickoff>now).map((r:any)=>{const game=app.gameById(r.fixtureId),current=app.byId(r.fixtureId)?.markets.flatMap(m=>m.selections).find(s=>s.id===r.id),pick=evidenceSlipPick(r,game,current,[],now);return {...r,odds:pick?.bestOdds??0,pricing:pick?.pricing==='quoted'?'quoted':'unpriced',quoteObservedAt:pick?.evidence.observedAt??null};}));
 $effect(()=>{if(allowed){selected;requestAnimationFrame(()=>document.querySelector('[aria-label="Rollover day"] [aria-pressed="true"]')?.scrollIntoView({block:'nearest',inline:'center'}));}});
 const result=$derived(rolloverTickets(priced,selected,now,records));
 async function record(ticket:any){if(!allowed||!auth.client||saving)return;saving=true;error='';try{await auth.client.mutation(anyApi.rollover.save,{day:selected,target:ticket.target,legs:ticket.picks.map((r:any)=>({fixtureId:r.fixtureId,key:r.key,matchTitle:r.matchTitle,selection:r.selection,kickoff:r.kickoff,odds:r.odds}))});notice='Ticket frozen for this day. Results and winning-day ticks update automatically after the provider confirms all final results.';}catch(e){error=(e as Error).message;}finally{saving=false;}}
 const pct=(p:number)=>(p*100).toFixed(1)+'%';const time=(t:number)=>new Date(t).toLocaleString('en-NG',{timeZone:'Africa/Lagos',dateStyle:'medium',timeStyle:'short'});
 function add(ticket:any){notice='';if(!allowed)return;const picks=ticket.picks.map((row:any)=>{const game=app.gameById(row.fixtureId),current=app.byId(row.fixtureId)?.markets.flatMap(m=>m.selections).find(s=>s.id===row.id);return evidenceSlipPick(row,game,current,rows.filter((r:any)=>r.fixtureId===row.fixtureId),Date.now());});if(picks.some((p:any)=>!p||p.pricing!=='quoted')){error='A fixture or price changed. Refresh before adding this ticket.';return;}if(app.slip.some(p=>!picks.some((q:any)=>q.id===p.id))){error='Your betslip contains other selections. Save or clear it first to preserve this ticket’s combined odds.';app.slipOpen=true;return;}for(const pick of picks)if(!app.inSlip(pick.id)&&!app.toggle(pick)){error='A selection could not be added. Review the betslip.';return;}notice='Ticket added. Save it from the betslip to retain your picks and evidence.';app.slipOpen=true;}
</script>
<svelte:head><title>Daily rollover research · PuntersEdge admin</title><meta name="robots" content="noindex,nofollow" /></svelte:head>
<section class="min-w-0 space-y-5">
 <header class="surface p-5 sm:p-7"><p class="text-xs font-bold uppercase tracking-widest text-model">🔁 Daily ticket research</p><h1 class="mt-2 text-3xl font-bold">Rollover selections</h1><p class="mt-3 max-w-3xl text-sm text-haze">30-day calendar with daily 2×, 3×, 5× and 10× targets across supported sports. Ranked evidence, current recorded quotes and a conservative probability screen. Each fixture appears in at most one ticket for the day.</p><div class="mt-4 flex flex-wrap gap-3"><button class="btn-primary" disabled={!allowed||loading} onclick={load}>{loading?'Refreshing…':'Refresh selections'}</button><button class="btn-secondary" onclick={()=>app.slipOpen=true}>🧾 Open betslip · {app.slip.length}</button><a class="btn-secondary" href="/admin/evidence/history">📜 Evidence history</a></div>{#if updated}<p class="mt-3 text-xs text-haze">Evidence published {time(updated)} WAT</p>{/if}</header>
 {#if !checked}<div class="workspace-state">Checking administrator access…</div>{:else if !allowed}<div class="workspace-state"><h2>Administrator access required</h2><a href="/login?next=%2Fadmin%2Frollover">Sign in</a></div>{:else}
 <div class="surface border border-amber-400/40 p-4 text-sm"><strong>Research screen · no guaranteed streak</strong><p class="mt-2">A model percentage is an estimate. Recurrence describes past comparable outcomes. Combined probabilities below multiply conservative screening probabilities and assume independent matches; they are not calibrated ticket win rates. Rolling all winnings risks the full balance on every day.</p><p class="mt-2">Even a ticket with a true 90% daily win chance has only {(100*.9**30).toFixed(1)}% chance of winning all 30 days. Future-day selections appear only when published fixtures, sufficient evidence and fresh prices exist.</p></div>
 <nav class="flex max-w-full gap-2 overflow-x-auto pb-2" aria-label="Rollover day">{#each dates as day}<button class="btn-secondary shrink-0" class:selected={selected===day} aria-pressed={selected===day} onclick={()=>selected=day}>{day===rolloverDay(now)?'Today · ':''}{day}{#each records.filter(r=>r.day===day&&r.status==='won') as won}<span class="ml-1 text-model">✓{won.target}×</span>{/each}</button>{/each}</nav>
 <nav class="flex flex-wrap gap-2" aria-label="Daily odds targets">{#each [2,3,5,10] as target}{@const record=records.find(r=>r.day===selected&&r.target===target)}<a class="btn-secondary" href={'#rollover-'+target}>{record?.status==='won'?'✓ ':record?.status==='lost'?'✕ ':record?.status==='void'?'↩ ':''}{target}× · {record?.status??'Unrecorded'}</a>{/each}</nav>
 {#if error}<p class="surface p-4 text-loss" role="alert">{error}</p>{/if}{#if notice}<p class="surface p-4 text-model" role="status">{notice}</p>{/if}
 <div class="surface p-4 text-sm text-haze">{result.eligible} qualified options · Quote maximum age 30 minutes · At least 20 comparable binary outcomes · Positive edge against the lower of Model % and historical 95% win-rate floor · Target tolerance ±10% · Up to 12 distinct fixtures per ticket.</div>
 <div class="grid min-w-0 gap-5 xl:grid-cols-2">{#each result.tickets as ticket}{@const saved=records.find(r=>r.day===selected&&r.target===ticket.target)}{@const settled=records.filter(r=>r.target===ticket.target&&r.day>=rolloverDay(now-29*86400000)&&r.day<=rolloverDay(now)&&['won','lost'].includes(r.status))}{@const wins=settled.filter(r=>r.status==='won').length}<article id={'rollover-'+ticket.target} class="surface min-w-0 overflow-hidden p-4 sm:p-5"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-2xl font-bold text-book">{ticket.target}× combined target</h2><span class="rounded-full bg-model/10 px-3 py-1 text-sm">{ticket.picks.length} selections</span></div>
  <p class="mt-3 text-sm font-semibold text-model">{rolloverStreak(records,ticket.target,now)} consecutive verified winning days</p><p class="mt-1 text-xs text-haze">Last 30 days: {wins} won / {settled.length} won-or-lost tickets · {settled.length?pct(wins/settled.length):'No settled accuracy yet'}. Pending and returned tickets excluded.</p>
 {#if saved}<div class="mt-4 rounded-xl border border-line p-3"><strong class={saved.status==='won'?'text-model':saved.status==='lost'?'text-loss':'text-book'}>{saved.status==='won'?'✓ Successful':saved.status==='lost'?'✕ Lost':saved.status} · {saved.totalOdds.toFixed(2)} odds</strong><p class="mt-1 text-xs text-haze">Frozen daily ticket · {saved.legs.length} selections</p><ol class="mt-3 space-y-2 text-sm">{#each saved.legs as leg}<li><a href="/match?id={encodeURIComponent(leg.fixtureId)}" class="hover:underline">{leg.matchTitle}</a> · {leg.selection} @ {leg.odds.toFixed(2)}</li>{/each}</ol>{#if saved.status==='pending'}<p class="mt-3 font-semibold text-book">⏳ Automatic settlement pending</p><p class="mt-2 text-xs text-haze">The results pipeline checks every leg against verified final scores and automatically marks win, loss or void. No manual grading is needed.</p>{/if}</div>{:else if !ticket.picks.length}<p class="mt-4 text-sm text-haze">No distinct combination passes this day’s evidence, positive-edge and fresh-price requirements within {(ticket.target*.9).toFixed(2)}–{(ticket.target*1.1).toFixed(2)} odds. Refresh when new fixtures or quotes arrive.</p>{:else}<div class="my-4 grid grid-cols-2 gap-3 text-sm"><p>Recorded combined odds<strong class="block text-xl text-book">{ticket.odds.toFixed(2)}</strong></p><p>Conservative screen product<strong class="block text-xl text-model">{pct(ticket.probability)}</strong></p><p>Screened ticket loss risk<strong class="block text-loss">{pct(1-ticket.probability)}</strong></p><p>30 identical independent days<strong class="block">{(100*ticket.probability**30).toFixed(6)}% all-win illustration</strong></p></div>
 <ol class="space-y-3">{#each [...ticket.picks].sort((a,b)=>b.modelProb-a.modelProb) as row,i}<li class="rounded-xl border border-line bg-ink/50 p-3"><a class="fixture-name font-semibold hover:underline" href="/match?id={encodeURIComponent(row.fixtureId)}">{i+1}. {row.matchTitle}</a><p class="mt-1 break-words text-xs text-haze">{row.sport} · {row.league}{row.country?' · '+row.country:''}{row.tournament&&row.tournament!==row.league?' · '+row.tournament:''} · {time(row.kickoff)} WAT</p><p class="mt-2 font-bold">{row.selection} <span class="text-book">@ {row.odds.toFixed(2)}</span></p><p class="mt-1 text-xs">Model {pct(row.modelProb)} · Historical {row.cohort.won}/{row.cohort.binaryN} ({pct(row.cohort.strikeRate)}) · 95% floor {pct(row.cohort.interval.low)}</p><meter class="mt-2 w-full" min="0" max="1" value={row.cohort.interval.low} aria-label="Historical win-rate lower bound"></meter><p class="mt-1 text-xs text-haze">Conservative screening edge {pct(row.conservativeEdge)} · Same exact market, model band and source cohort; not independent profit validation.</p></li>{/each}</ol><button class="btn-secondary mt-4 w-full" disabled={saving} onclick={()=>record(ticket)}>Record & freeze daily ticket</button><button class="btn-primary mt-3 w-full" onclick={()=>add(ticket)}>+ Add ticket to betslip</button>{/if}</article>{/each}</div>
 <details class="surface p-4"><summary class="cursor-pointer py-2 font-bold">Excluded options & selection method</summary><p class="mt-3 text-sm text-haze">{Object.entries(result.rejected).map(([k,v])=>`${k}: ${v}`).join(' · ')}. Tickets use a bounded deterministic search maximizing the conservative probability product. Smaller targets are filled first; their fixtures are reserved before larger targets. Markets with push or partial-settlement evidence are excluded from this binary calculation. No automatic stakes or payments are placed. Save each accepted ticket in the existing betslip workflow.</p></details>
 {/if}
</section>
<style>.selected{outline:2px solid #facc15;outline-offset:2px}meter{accent-color:#34d399}button:focus-visible,a:focus-visible{outline:3px solid #facc15;outline-offset:3px}</style>
